#!/usr/bin/env node
/* ZakTracking - the four templates that were approved but never sent.
 *
 *   cod_reminder     one nudge when a COD order goes unanswered for 6 hours
 *   refund_initiated the refunds/create webhook, at the refund's own amount
 *   review_request   3 days after the parcel was delivered
 *   back_in_stock    served from a waiting list a sold-out card fills in
 *
 * Safe to run twice. Every file is checked before anything is written, and
 * if even one is not what this patch expects, nothing is written at all.
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const FILES = [
  {
    "path": "prisma/schema.prisma",
    "fromShas": [
      "b1dbbfa6614d67d8728fefcb15bf648f37c8672630612b1ba98ffd462d7bc516"
    ],
    "toSha": "22c9ae9ae89a1fcc07ca2cd17125ff4e5a84d811a7d8f6f28b47bf1e60bf7b85",
    "b64": ""
  },
  {
    "path": "app/lib/webhook.server.ts",
    "fromShas": [
      "c10501ec26bae66309c1d4d137c03b3f611f27618856588be1261cf615dd4f41"
    ],
    "toSha": "652dc3b50b64f3611945fba382f64350e0f66a81de5f5d5991529c4d0b991016",
    "b64": ""
  },
  {
    "path": "app/lib/followups.server.ts",
    "fromShas": [],
    "toSha": "98028a2c6e51d2fc9aea189b76471baef3ac5bd1c29b44659e3e2c58559b86b7",
    "b64": ""
  },
  {
    "path": "app/routes/webhooks.refunds.tsx",
    "fromShas": [],
    "toSha": "e741fe7bddcb42f3c253443e82f9f9686c6fc6183c3209a81c25c0ac9707fd31",
    "b64": ""
  },
  {
    "path": "app/routes/webhooks.products.tsx",
    "fromShas": [],
    "toSha": "187b7233ba272a0a817bf83a6c6ee6068ac75e4bca375c1ea1bd8e422a97f4bd",
    "b64": ""
  },
  {
    "path": "app/routes/proxy.track.stock.tsx",
    "fromShas": [],
    "toSha": "b56216274d0dd40af7a643b272a4f3faf8c2eae854e0b124eec76b3918ba7d99",
    "b64": ""
  },
  {
    "path": "app/routes/api.cron.tsx",
    "fromShas": [
      "64769b7b4fc650ff701b4a2c6ad9fada80b9c879fa30fb58ae32e3ff3eca0ba1"
    ],
    "toSha": "eb29ec8e49c47763dd124f92b08df9683cb54678ff0a4cf168d9b3f9032e4e86",
    "b64": ""
  },
  {
    "path": "shopify.app.toml",
    "fromShas": [
      "823763b8060b646474be1c886956cedfee9a85d98299d4aa6907b97ccda6ed1d"
    ],
    "toSha": "c79587db1eb2aec5dbdf9ae0c31cb8e782206070bc03826e8403dd6c0320c2bb",
    "b64": ""
  }
];

const sha = (b) => crypto.createHash("sha256").update(b).digest("hex");
const norm = (b) => Buffer.from(b.toString("utf8").replace(/\r\n/g, "\n"), "utf8");

let done = 0;
const todo = [];

for (const f of FILES) {
  const p = path.resolve(f.path);
  const want = Buffer.from(f.b64, "base64");

  if (!fs.existsSync(p)) {
    if (f.fromShas.length) {
      console.error("MISSING  " + f.path + " - is this the zaktracking repo root?");
      process.exit(1);
    }
    todo.push({ p, want, f });
    continue;
  }

  const have = fs.readFileSync(p);
  const hs = sha(have), ns = sha(norm(have));

  if (hs === f.toSha || ns === f.toSha) { done++; continue; }
  if (f.fromShas.includes(hs) || f.fromShas.includes(ns)) { todo.push({ p, want, f }); continue; }

  console.error("CHANGED  " + f.path);
  console.error("         This file is not the version this patch was built against.");
  console.error("         Nothing has been written. Send me the file and I will rebuild it.");
  process.exit(1);
}

if (!todo.length) {
  console.log("Already applied - " + done + " file(s) are up to date. Nothing to do.");
  process.exit(0);
}

for (const t of todo) {
  fs.mkdirSync(path.dirname(t.p), { recursive: true });
  fs.writeFileSync(t.p, t.want);
  if (sha(fs.readFileSync(t.p)) !== t.f.toSha) {
    console.error("WRITE FAILED  " + t.f.path);
    process.exit(1);
  }
  console.log("written  " + t.f.path);
}

console.log("");
console.log("Done. " + todo.length + " file(s) written, " + done + " already correct.");
console.log("");
console.log("Next, one command at a time:");
console.log("  npx prisma migrate dev --name followups");
console.log("  git add -A");
console.log("  git commit -m \"the four templates that never sent\"");
console.log("  git push");
console.log("  npm run deploy      <- registers the two new webhooks with Shopify");
